'use client';
import { useEffect, useMemo, useRef, useState, type CSSProperties } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import { useInView, useStudioMotion } from '../../../motion';
import { resolveParams, type EffectMeta, type ParamValues } from '../../../types';
import SplitLineReveal from '../../../effects/split-line-reveal';
import { meta as splitMeta } from '../../../effects/split-line-reveal/meta';
import { FIGURE_DESCRIPTION, STEPS, createPainter, valley } from './valley';
import { ValleySvg } from './ValleySvg';
import s from './styles.module.css';

if (typeof window !== 'undefined') gsap.registerPlugin(ScrollTrigger, useGSAP);

/** Every recipe param from its meta (defaults), then this demo's overrides. */
const recipe = <T,>(m: EffectMeta, overrides: ParamValues = {}): T => resolveParams(m.params, overrides) as unknown as T;

const NARROW = 1024; // px of demo width below which the figure sits above the text

/** Decorative contour hill for the title card (static). */
function TitleContours() {
  const rings = useMemo(() => Array.from({ length: 13 }, (_, k) => {
    const r = 40 + k * 34;
    const pts = Array.from({ length: 73 }, (_, i) => {
      const a = (i / 72) * Math.PI * 2;
      const w = 1 + 0.08 * Math.sin(a * 3 + k * 0.7) + 0.05 * Math.sin(a * 5 - k);
      return `${(420 + Math.cos(a) * r * w * 1.25).toFixed(1)} ${(300 + Math.sin(a) * r * w * 0.8).toFixed(1)}`;
    });
    return `M${pts.join('L')}Z`;
  }), []);
  return (
    <svg className={s.titleArt} viewBox="0 0 840 600" aria-hidden="true" focusable="false">
      {rings.map((d, k) => <path key={k} d={d} className={s.contour} />)}
    </svg>
  );
}

/** The closing statement: the split-line recipe mounts as it comes into view, so its entrance is seen. */
function ClosingTitle() {
  const ref = useRef<HTMLDivElement>(null);
  const near = useInView(ref, { amount: 0.5 });
  const { reduced } = useStudioMotion();
  const text = 'A river is a slow argument with its valley.';
  return (
    <div ref={ref} className={s.closingTitle}>
      {near || reduced ? <SplitLineReveal params={recipe(splitMeta, { text, stagger: 56, duration: 820, rise: 110, skew: false })} /> : <h2 className={s.placeholder}>{text}</h2>}
    </div>
  );
}

export default function ScrollNarrative() {
  const { reduced } = useStudioMotion();
  const root = useRef<HTMLDivElement>(null);
  const stepsRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const railRef = useRef<HTMLElement>(null);
  const trigger = useRef<ScrollTrigger | null>(null);
  const [active, setActive] = useState(0);
  const initial = useMemo(() => valley(0), []);
  const statics = useMemo(() => (reduced ? STEPS.map((_, i) => valley(i)) : null), [reduced]);

  useGSAP(() => {
    const steps = stepsRef.current;
    const svg = svgRef.current;
    const rail = railRef.current;
    const el = root.current;
    if (reduced || !steps || !svg || !rail || !el) return;
    const paint = createPainter(svg);
    const narrow = () => el.clientWidth < NARROW;
    const n = STEPS.length;
    const state = { t: 0 };
    let drawn = -1;
    const draw = () => {
      if (Math.abs(state.t - drawn) < 0.0004) return;
      drawn = state.t;
      paint(valley(state.t));
    };
    // One unit of timeline per step. Each hand-over sits across a step boundary, so every stage rests
    // while its text crosses the reading line (centre of the viewport, or below the figure when narrow).
    const tl = gsap.timeline({
      defaults: { ease: 'none' },
      onUpdate: draw,
      scrollTrigger: {
        trigger: steps,
        start: () => (narrow() ? 'top 76%' : 'top center'),
        end: () => (narrow() ? 'bottom 76%' : 'bottom center'),
        scrub: 0.6,
        invalidateOnRefresh: true,
        onUpdate: (self) => {
          rail.style.setProperty('--p', self.progress.toFixed(4));
          const i = Math.min(n - 1, Math.floor(self.progress * n));
          setActive((prev) => (prev === i ? prev : i));
        },
      },
    });
    tl.to({}, { duration: 0.75 });
    for (let i = 1; i < n; i++) tl.to(state, { t: i, duration: 0.5 }).to({}, { duration: i < n - 1 ? 0.5 : 0.75 });
    trigger.current = tl.scrollTrigger ?? null;

    // The demo frame can change width without a window resize (preview widths), and web fonts move layout.
    let width = el.clientWidth;
    let timer = 0;
    const ro = new ResizeObserver(() => {
      if (el.clientWidth === width) return;
      width = el.clientWidth;
      window.clearTimeout(timer);
      timer = window.setTimeout(() => ScrollTrigger.refresh(), 140);
    });
    ro.observe(el);
    let alive = true;
    void document.fonts?.ready.then(() => { if (alive) ScrollTrigger.refresh(); });
    return () => { alive = false; ro.disconnect(); window.clearTimeout(timer); trigger.current = null; rail.style.removeProperty('--p'); };
  }, { scope: root, dependencies: [reduced], revertOnUpdate: true });

  // Reduced motion: chapters are stacked, so the rail follows whichever step crosses the middle of the screen.
  useEffect(() => {
    const steps = stepsRef.current;
    if (!reduced || !steps || typeof IntersectionObserver === 'undefined') return;
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) if (e.isIntersecting) setActive(Number((e.target as HTMLElement).dataset.step));
    }, { rootMargin: '-40% 0px -55% 0px' });
    steps.querySelectorAll('[data-step]').forEach((x) => io.observe(x));
    return () => io.disconnect();
  }, [reduced]);

  const goTo = (i: number): void => {
    const heading = root.current?.querySelector<HTMLElement>(`#rv-step-${STEPS[i].id}`);
    const st = trigger.current;
    if (!reduced && st) window.scrollTo({ top: st.start + (st.end - st.start) * ((i + 0.5) / STEPS.length), behavior: 'smooth' });
    else heading?.scrollIntoView({ block: 'start' });
    heading?.focus({ preventScroll: true });
  };

  const railStyle = (reduced ? { '--p': (active + 1) / STEPS.length } : undefined) as CSSProperties | undefined;

  return (
    <div ref={root} className={s.root} data-mode={reduced ? 'static' : 'scrub'}>
      <header className={s.title}>
        <div className={s.titleText}>
          <p className={s.kicker}>Fieldbook No. 7 <span aria-hidden="true">·</span> a river in five stages <span aria-hidden="true">·</span> sample content</p>
          <h2 className={s.headline}>The Long <em>Bend</em></h2>
          <p className={s.standfirst}>How a small river spends thousands of years carving, widening and finally furnishing the valley it lives in.</p>
          <p className={s.byline}>Text and survey drawings for a fictional river, the Vell. The processes are real and simplified; the place is not.</p>
          <a className={s.skip} href="#rv-closing">Skip the five stages</a>
        </div>
        <TitleContours />
      </header>

      <div className={s.story}>
        <nav ref={railRef} className={s.rail} aria-label="Stages of the river" style={railStyle}>
          <p className={s.railHead} aria-hidden="true">Stages</p>
          <ol className={s.railList}>
            {STEPS.map((st, i) => (
              <li key={st.id} style={{ '--i': i } as CSSProperties}>
                <button type="button" className={s.railBtn} aria-current={active === i ? 'step' : undefined} onClick={() => goTo(i)}>
                  <span className={s.seg} aria-hidden="true" />
                  <span className={s.railNum}>{st.numeral}</span>
                  <span className={s.railName}>{st.short}</span>
                </button>
              </li>
            ))}
          </ol>
        </nav>

        {!reduced ? (
          <figure className={s.figure}>
            <div className={s.figHead} aria-hidden="true">
              <span>Fig. {active + 1}</span>
              <span>Stage {STEPS[active].numeral} / V</span>
            </div>
            <ValleySvg ref={svgRef} g={initial} labelId="rv-fig-desc" />
            <figcaption className={s.figcap}>{STEPS[active].caption}</figcaption>
            <p id="rv-fig-desc" className="mk-sr-only">{FIGURE_DESCRIPTION}</p>
          </figure>
        ) : null}

        <div ref={stepsRef} className={s.steps}>
          {STEPS.map((st, i) => (
            <section key={st.id} className={s.step} data-step={i} aria-labelledby={`rv-step-${st.id}`}>
              {statics ? (
                <figure className={s.stepFigure}>
                  <ValleySvg g={statics[i]} />
                  <figcaption className={s.figcap}>{st.caption}</figcaption>
                </figure>
              ) : null}
              <div className={s.stepText}>
                <p className={s.stepNum} aria-hidden="true">{st.numeral}</p>
                <h3 id={`rv-step-${st.id}`} className={s.stepTitle} tabIndex={-1}>{st.title}</h3>
                <p className={s.stepBody}>{st.body}</p>
                <p className={s.look}><span className={s.lookKey}>Look for</span> {st.look}</p>
              </div>
            </section>
          ))}
        </div>
      </div>

      <section id="rv-closing" className={s.closing} aria-labelledby="rv-closing-h" tabIndex={-1}>
        <p id="rv-closing-h" className={s.kicker}>After the fifth stage</p>
        <ClosingTitle />
        <div className={s.closingGrid}>
          <div>
            <h3 className={s.closingH}>What the valley keeps</h3>
            <p className={s.closingP}>Every stage leaves something behind. The steep upper valley keeps its V; the middle keeps the scars of loops that were cut off; the lower valley keeps its terraces, each one a floor the river made and then abandoned. Read together, they are the river&rsquo;s own account of where it has been.</p>
          </div>
          <div>
            <h3 className={s.closingH}>On a walk, look for</h3>
            <ol className={s.lookList}>
              <li>A steep cut bank facing a sandy inside bend.</li>
              <li>A crescent of still water near, but not on, the river.</li>
              <li>A low step at the edge of flat fields: a terrace.</li>
            </ol>
          </div>
        </div>
        <p className={s.colophon}>
          Method: meander shapes are drawn with a sine-generated curve, a standard approximation of real river bends; valley contours and the cross-section are diagrams, not surveys. The Vell, its valley and its five stages are fictional sample content.
        </p>
      </section>
    </div>
  );
}

/* The Long Bend — survey-map editorial. Paper, ink, one water colour; serif display, mono survey labels. */
.root {
  --rv-water: #0b6178;
  --rv-pad: clamp(16px, 4cqi, 56px);
  position: relative;
  overflow-x: clip;
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}
:global([data-theme='dark']) .root { --rv-water: #5cc3e0; }

.kicker,
.figHead,
.railHead,
.lookKey,
.closingH {
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mk-ink-muted, #5c5a52);
}

/* ── Title card ─────────────────────────────────────────────── */
.title {
  position: relative;
  display: grid;
  align-content: end;
  min-height: calc(100svh - 44px);
  padding: clamp(40px, 7cqi, 112px) var(--rv-pad) clamp(40px, 6cqi, 88px);
  border-bottom: 1px solid var(--mk-line, #11110f24);
  overflow: clip;
}
.titleText { position: relative; z-index: 1; display: grid; gap: 18px; }
.headline {
  margin: 0;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-size: clamp(4.2rem, 1rem + 15cqi, 15rem);
  font-weight: 400;
  line-height: 0.84;
  letter-spacing: -0.035em;
}
.headline em { font-style: italic; color: var(--rv-water); }
.standfirst {
  margin: 10px 0 0;
  max-width: 28ch;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-size: clamp(1.35rem, 0.9rem + 1.6cqi, 2.15rem);
  line-height: 1.16;
  text-wrap: balance;
}
.byline { margin: 0; max-width: 54ch; font-size: 0.9375rem; line-height: 1.55; color: var(--mk-ink-muted, #5c5a52); }
.skip {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  min-height: 36px;
  margin-top: 6px;
  padding: 0 14px;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: 999px;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mk-ink, #11110f);
  text-decoration: none;
}
.skip:hover { background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); }
.titleArt {
  position: absolute;
  z-index: 0;
  top: -6%;
  right: -22cqi;
  width: max(560px, 88cqi);
  height: auto;
  pointer-events: none;
}
@container (min-width: 64rem) {
  .title { grid-template-columns: minmax(0, 1fr); }
  .titleArt { right: -12cqi; top: -16%; width: min(66cqi, 1000px); }
}

/* ── Story: rail | steps | sticky figure ────────────────────── */
.story { position: relative; padding: 0 var(--rv-pad); }

.rail {
  position: sticky;
  top: 44px;
  z-index: 3;
  margin: 0 calc(-1 * var(--rv-pad));
  padding: 6px var(--rv-pad);
  background: var(--mk-bg, #f3f0e8);
  border-bottom: 1px solid var(--mk-line, #11110f24);
}
.railHead { display: none; }
.railList { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; margin: 0; padding: 0; list-style: none; }
.railBtn {
  position: relative;
  display: grid;
  grid-template-rows: 3px auto;
  justify-items: center;
  gap: 5px;
  width: 100%;
  min-height: 40px;
  padding: 4px 0 2px;
  border: 0;
  background: none;
  color: var(--mk-ink-muted, #5c5a52);
  font: inherit;
  cursor: pointer;
}
.railBtn:hover, .railBtn[aria-current] { color: var(--mk-ink, #11110f); }
.railBtn:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; border-radius: 3px; }
.seg { position: relative; width: 100%; height: 3px; overflow: clip; border-radius: 2px; background: var(--mk-line, #11110f24); }
.seg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--rv-water);
  transform-origin: left center;
  scale: clamp(0, calc(var(--p, 0) * 5 - var(--i, 0)), 1) 1;
}
.railNum { font-family: var(--mk-font-serif, Georgia, serif); font-size: 1.125rem; font-style: italic; line-height: 1; }
.railBtn[aria-current] .railNum { color: var(--rv-water); }
.railName { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.figure {
  position: sticky;
  top: calc(44px + 54px);
  z-index: 2;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 6px;
  height: 50svh;
  margin: 0 calc(-1 * var(--rv-pad));
  padding: 8px var(--rv-pad) 10px;
  background: var(--mk-bg, #f3f0e8);
  border-bottom: 1px solid var(--mk-line, #11110f24);
}
.figHead { display: flex; justify-content: space-between; gap: 12px; }
.plan { display: block; width: 100%; height: 100%; min-height: 0; }
.figcap { margin: 0; max-width: 52ch; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }

.steps { position: relative; z-index: 1; }
.step { display: grid; align-content: center; min-height: 72svh; padding: 6svh 0; }
.stepText { display: grid; gap: 14px; max-width: 34rem; }
.stepNum { margin: 0; font-family: var(--mk-font-serif, Georgia, serif); font-size: clamp(2.75rem, 2rem + 2cqi, 4rem); font-style: italic; line-height: 0.9; color: var(--rv-water); }
.stepTitle {
  margin: 0;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-size: clamp(2rem, 1.2rem + 2.4cqi, 3.25rem);
  font-weight: 400;
  line-height: 1.02;
  letter-spacing: -0.02em;
  text-wrap: balance;
  scroll-margin-top: 132px;
}
.stepTitle:focus { outline: none; }
.stepTitle:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 4px; }
.stepBody { margin: 0; font-size: clamp(1.0625rem, 0.95rem + 0.3cqi, 1.1875rem); line-height: 1.62; text-wrap: pretty; }
.look { margin: 4px 0 0; padding-top: 12px; border-top: 1px solid var(--mk-line, #11110f24); font-size: 0.9375rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); }
.lookKey { margin-right: 8px; color: var(--mk-ink, #11110f); }

@container (min-width: 64rem) {
  .story {
    display: grid;
    grid-template-columns: 9.5rem minmax(0, 33rem) minmax(0, 1fr);
    column-gap: clamp(28px, 3.5cqi, 64px);
    max-width: 1480px;
    margin: 0 auto;
  }
  .rail {
    grid-column: 1;
    grid-row: 1;
    align-self: start;
    top: calc(44px + 48px);
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
  }
  .railHead { display: block; margin-bottom: 14px; }
  .railList { grid-template-columns: minmax(0, 1fr); gap: 2px; }
  .railBtn { grid-template-columns: 3px 2.1rem minmax(0, 1fr); grid-template-rows: none; justify-items: start; align-items: center; gap: 10px; min-height: 46px; text-align: start; font-size: 0.875rem; }
  .seg { width: 3px; height: auto; align-self: stretch; }
  .seg::after { transform-origin: center top; scale: 1 clamp(0, calc(var(--p, 0) * 5 - var(--i, 0)), 1); }
  .railName { position: static; width: auto; height: auto; margin: 0; overflow: visible; clip-path: none; white-space: normal; line-height: 1.25; }
  .railBtn[aria-current] .railName { font-weight: 600; }
  .steps { grid-column: 2; grid-row: 1; }
  .step { min-height: 100svh; padding: 0; }
  .figure {
    grid-column: 3;
    grid-row: 1;
    align-self: start;
    top: 44px;
    height: calc(100svh - 44px);
    margin: 0;
    padding: 28px 0 24px;
    border: 0;
    background: none;
  }
}

/* Reduced motion: an ordinary article. Each stage carries its own still drawing; nothing is pinned. */
.root[data-mode='static'] .step { min-height: 0; padding: 44px 0; align-content: start; border-bottom: 1px solid var(--mk-line, #11110f24); }
.root[data-mode='static'] .step:last-child { border-bottom: 0; }
.stepFigure { display: grid; gap: 8px; max-width: 24rem; margin: 0 0 22px; }
.stepFigure .plan { height: auto; aspect-ratio: 3 / 4; }
@container (min-width: 64rem) {
  .root[data-mode='static'] .steps { grid-column: 2 / 4; }
  .root[data-mode='static'] .step { grid-template-columns: minmax(0, 22rem) minmax(0, 34rem); gap: 56px; align-items: center; }
  .root[data-mode='static'] .stepFigure { margin: 0; }
}

/* ── Survey drawing ─────────────────────────────────────────── */
.paper { fill: var(--mk-surface, #fbf9f4); }
.grid path { fill: none; stroke: var(--mk-line, #11110f24); stroke-width: 1; }
.floor { fill: var(--mk-surface-2, #e9e5da); }
.contour { fill: none; stroke: var(--mk-ink-muted, #5c5a52); stroke-width: 0.8; }
.contourIndex { fill: none; stroke: var(--mk-ink, #11110f); stroke-width: 1.2; }
.terrace { fill: none; stroke: var(--mk-ink, #11110f); stroke-width: 7; stroke-dasharray: 1.2 4.6; }
.scar { fill: none; stroke: var(--mk-ink-muted, #5c5a52); stroke-width: 2.2; stroke-dasharray: 0.1 6; stroke-linecap: round; }
.bars { fill: none; stroke: var(--mk-ink-muted, #5c5a52); stroke-width: 3.4; stroke-dasharray: 0.1 6.4; stroke-linecap: round; }
.oxbow { fill: none; stroke: color-mix(in oklab, var(--rv-water) 58%, var(--mk-surface, #fbf9f4)); stroke-linecap: round; stroke-linejoin: round; }
.channel { fill: none; stroke: var(--rv-water); stroke-linecap: round; stroke-linejoin: round; }
.sectionLine { fill: none; stroke: var(--mk-ink, #11110f); stroke-width: 1; stroke-dasharray: 10 6 2 6; }
.mapLabel { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 13px; letter-spacing: 0.06em; text-transform: uppercase; fill: var(--mk-ink-muted, #5c5a52); }
.north { fill: var(--mk-ink, #11110f); }
.inset { fill: var(--mk-surface, #fbf9f4); stroke: var(--mk-line-strong, #11110f); stroke-width: 1; }
.ground { fill: var(--mk-surface-2, #e9e5da); stroke: var(--mk-ink, #11110f); stroke-width: 1.4; stroke-linejoin: round; }
.water { fill: var(--rv-water); }

/* ── Closing ────────────────────────────────────────────────── */
.closing {
  display: grid;
  gap: 28px;
  max-width: 1480px;
  margin: 0 auto;
  padding: clamp(72px, 11cqi, 168px) var(--rv-pad) clamp(64px, 8cqi, 120px);
  border-top: 1px solid var(--mk-line, #11110f24);
  scroll-margin-top: 60px;
}
.closing:focus { outline: none; }
.closingTitle h2,
.placeholder {
  margin: 0;
  max-width: 15ch;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-size: clamp(2.6rem, 1rem + 6cqi, 6.75rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--mk-ink, #11110f);
}
.placeholder { opacity: 0; }
.closingGrid { display: grid; gap: 32px; max-width: 70rem; }
@container (min-width: 48rem) { .closingGrid { grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); gap: 56px; } }
.closingH { margin-bottom: 12px; padding-bottom: 10px; border-bottom: 1px solid var(--mk-line, #11110f24); }
.closingP { margin: 0; max-width: 60ch; font-size: 1.0625rem; line-height: 1.62; }
.lookList { display: grid; gap: 10px; margin: 0; padding-left: 1.3em; list-style: decimal; font-size: 1.0625rem; line-height: 1.5; }
.lookList li::marker { font-family: var(--mk-font-serif, Georgia, serif); font-style: italic; color: var(--rv-water); }
.colophon { margin: 12px 0 0; max-width: 72ch; padding-top: 16px; border-top: 1px solid var(--mk-line, #11110f24); font-size: 0.8125rem; line-height: 1.55; color: var(--mk-ink-muted, #5c5a52); }

/**
 * Plan-view and cross-section geometry of the (fictional) Vell valley at a continuous stage t ∈ [0, 4].
 * Pure and deterministic: the same t always gives the same drawing, so the scrubbed figure, the static
 * reduced-motion figures and a reload mid-page all agree.
 *
 * The channel is a sine-generated curve (direction angle θ = ω·sin(2πs) along the arc length s), the standard
 * approximation of real meander bends: small ω is a nearly straight stream, ω near 2 rad gives looping bends.
 */

